import{z as A,x as r,o as i,c as m,q as o,j as B,D as t,d as E,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"LSM 引擎的实现","description":"","frontmatter":{"title":"LSM 引擎的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dbk-lsm-implementation.md","filePath":"cs/dbk-lsm-implementation.md","lastUpdated":1791063341000}'),c={name:"cs/dbk-lsm-implementation.md"};function p(d,a,L,C,f,F){const n=r("Mermaid");return i(),m("div",null,[a[2]||(a[2]=o('<h1 id="lsm-引擎的实现" tabindex="-1">LSM 引擎的实现 <a class="header-anchor" href="#lsm-引擎的实现" aria-label="Permalink to &quot;LSM 引擎的实现&quot;">​</a></h1><div class="epigraph"><p>B+ 树把麻烦摊在每一次写入上，LSM 把麻烦攒起来留给自己；引擎的全部纪律，都写在「文件不可变」四个字里。</p><footer>—— 据 O&#39;Neil, Cheng, Gawlick and O&#39;Neil, *Acta Informatica*, 1996；LevelDB 与 RocksDB 设计文档整理</footer></div><p><a href="/cs/dbk-btree-concurrency">上一课</a>把 B+ 树的并发写在闩的全序上：读者靠右链在移动的树里走。LSM 引擎换一条路线——不做原地更新，写永远是「追加一个新文件」。主干与优化课已经算过 <a href="/cs/lsm-compaction">LSM 与 compaction</a>、<a href="/cs/lsm-read-amplification">读放大与布隆</a>的机制账；本课写实现骨架：一个能跑的 LSM 引擎由哪些组件构成、组件之间靠什么不变量咬合、写路径上每一步把数据放在哪。后面的执行器把它当「按序吐键的迭代器」来用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实现一上来要答三个问题。内存表选什么结构——要并发插入、要范围扫描、要能整体刷盘；文件格式怎么定——不可变文件写坏无法原位修补，校验与索引必须内建；层与层之间的不变量是什么——没有不变量，读就要合并任意多个文件。缺了会错在哪：墓碑若在高层 compaction 提前丢掉，被删的键还躺在更老的层里，读路径一路归并下来，删除的键「复活」——LSM 最经典的正确性事故；L0 文件若不按新旧排序读，覆盖同键的两个版本谁赢全凭运气。</p><p><span class="marginnote">「墓碑」（tombstone）是一条「这个键删掉了」的标记记录，并不真去老文件里抹数据。它必须活着挡住更老层的同名键，直到 compaction 把全部历史归并到最底层才许撤——提前撤，被删的键就从最老的层里「复活」，这是 LSM 头号正确性事故。</span></p><h3 id="组件清单" tabindex="-1">组件清单 <a class="header-anchor" href="#组件清单" aria-label="Permalink to &quot;组件清单&quot;">​</a></h3><p>一个最小可用的 LSM 引擎是五件套。WAL，先于内存表落盘，保证内存丢失可重放（<a href="/cs/wal">WAL</a>的规则，日志机实现是本课程第 6 课的题目）。内存表，跳表——插入只改指针、无需再平衡，天然有序支持范围扫，刷盘时顺序遍历即得有序文件。不可变内存表队列，内存表写满先冻结排队，冻结期间读照常。SST 文件，数据块（键前缀压缩加重启点）、布隆过滤块、索引块、页脚，块级校验和——写坏一个块只废一个块。manifest，记录每层有哪些文件、每个文件的键区间与最大序号，它是唯一真相：文件的生效与废弃都是对 manifest 的一次原子切换。</p><p><span class="marginnote">LevelDB/RocksDB 的默认形状：L0 允许重叠、按文件号新者优先；\\(L_1\\) 起每层是一个不重叠的有序 run，下层容量约为上层的 10 倍。「不重叠」就是读的预算——在 \\(L_i\\) 上定位一个键至多碰一个文件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写路径是一条直线：追加 WAL 记录，插入内存表；写满则冻结并触发 flush——冻结表排序后写成 L0 的一个 SST，manifest 原子切换，然后才删 WAL 里对应段落。读路径是归并：点查从新到旧过内存表、L0 各文件（布隆先挡一道）、每层至多一个候选文件；范围扫描用归并迭代器把所有 run 按序吐出，同键新版本遮住旧版本——上一课「按序、可重试的迭代」在这里原样复用，只是来源从一棵树变成一组不可变文件。compaction 是后台的归并循环：按层大小对目标值之比打分，选出层与文件，把 \\(L_i\\) 的若干文件与 \\(L_{i+1}\\) 的重叠区间归并成新文件集，再原子切换 manifest。两次 compaction 之间，不变量由 manifest 单点维护，没有任何现场改动。</p>',11)),(i(),B(s,null,{default:t(()=>[l(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUT%5B%22%E5%86%99%E5%85%A5%22%5D%20--%3E%20WAL%5B%22%E8%BF%BD%E5%8A%A0%20WAL%22%5D%0A%20%20WAL%20--%3E%20MEM%5B%22%E6%8F%92%E5%85%A5%E5%86%85%E5%AD%98%E8%A1%A8%EF%BC%88%E8%B7%B3%E8%A1%A8%EF%BC%89%22%5D%0A%20%20MEM%20--%3E%20FULL%7B%22%E5%86%99%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20FULL%20--%3E%7C%E5%90%A6%7C%20PUT%0A%20%20FULL%20--%3E%7C%E6%98%AF%7C%20FRZ%5B%22%E5%86%BB%E7%BB%93%EF%BC%8C%E6%8E%92%E9%98%9F%20flush%22%5D%0A%20%20FRZ%20--%3E%20SST%5B%22%E6%8E%92%E5%BA%8F%E5%86%99%E5%87%BA%20L0%20SST%22%5D%0A%20%20SST%20--%3E%20MAN%5B%22manifest%20%E5%8E%9F%E5%AD%90%E5%88%87%E6%8D%A2%22%5D%0A%20%20MAN%20--%3E%20CMP%5B%22%E5%90%8E%E5%8F%B0%20compaction%EF%BC%9ALi%20%E5%BD%92%E5%B9%B6%E5%85%A5%20Li%2B1%22%5D%0A%20%20CMP%20--%3E%20GC%5B%22%E4%B8%A2%E5%A2%93%E7%A2%91%E4%B8%8E%E6%97%A7%E7%89%88%E6%9C%AC%EF%BC%88%E4%BB%85%E6%9C%80%E5%BA%95%E5%B1%82%EF%BC%89%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("引擎的正确性押在两条不变量上。其一，文件不可变：一经写出内容永不再改，读并发因此不需要任何闩——上一课的树闩在 LSM 里没有对应物；compaction 写新文件、切 manifest，老文件在引用计数归零前谁都还在用。其二，同键多版本按序号全序化：读快照带序号，任何 run 的同一键按（键，序号）排序，快照可见性就是一次比较；内存表与各层文件在归并迭代器里对齐后，新版本遮旧版本，墓碑遮一切更老版本。墓碑的回收因此有严格的位置约束：只有归并到最底层、确认键区间再无更老数据时才允许丢，中间层丢了就会复活。快照把回收再钉一道：长事务持着旧序号，相关版本一个都删不得——与 "),e("a",{href:"/cs/mvcc-gc"},"MVCC 版本回收"),E("同病，空间账单也同源。")],-1)),a[5]||(a[5]=e("p",null,"一次点查从新到旧要走哪些站：",-1)),(i(),B(s,null,{default:t(()=>[l(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%82%B9%E6%9F%A5%E6%9F%90%E4%B8%AA%E9%94%AE%22%5D%20--%3E%20MT%5B%22%E6%9F%A5%E6%B4%BB%E8%B7%83%E5%86%85%E5%AD%98%E8%A1%A8%22%5D%0A%20%20MT%20--%3E%20FZ%5B%22%E6%9F%A5%E5%86%BB%E7%BB%93%E5%86%85%E5%AD%98%E8%A1%A8%E9%98%9F%E5%88%97%22%5D%0A%20%20FZ%20--%3E%20L0%5B%22L0%20%E5%90%84%E6%96%87%E4%BB%B6%EF%BC%9A%E5%B8%83%E9%9A%86%E5%85%88%E6%8C%A1%E4%B8%80%E9%81%93%EF%BC%8C%E6%8C%89%E5%8F%B7%E6%96%B0%E8%80%85%E4%BC%98%E5%85%88%22%5D%0A%20%20L0%20--%3E%20LI%5B%22%E5%BE%80%E4%B8%8B%E6%AF%8F%E5%B1%82%E8%87%B3%E5%A4%9A%E4%B8%80%E4%B8%AA%E5%80%99%E9%80%89%E6%96%87%E4%BB%B6%22%5D%0A%20%20LI%20--%3E%20HIT%5B%22%E7%AC%AC%E4%B8%80%E4%B8%AA%E5%91%BD%E4%B8%AD%E7%9A%84%E7%89%88%E6%9C%AC%E8%83%9C%E5%87%BA%EF%BC%9A%E6%96%B0%E9%81%AE%E6%97%A7%22%5D%0A%20%20HIT%20--%3E%20TB%7B%22%E6%98%AF%E5%A2%93%E7%A2%91%EF%BC%9F%22%7D%0A%20%20TB%20--%3E%7C%22%E6%98%AF%22%7C%20NONE%5B%22%E8%BF%94%E5%9B%9E%EF%BC%9A%E9%94%AE%E5%B7%B2%E5%88%A0%E9%99%A4%22%5D%0A%20%20TB%20--%3E%7C%22%E5%90%A6%22%7C%20RET%5B%22%E8%BF%94%E5%9B%9E%E8%AF%A5%E7%89%88%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">初学者容易以为「文件不可变」是浪费空间的设计。实际它换来的是读路径零闩：文件写完就永远不变，谁也不会改你正在读的页，读者随便并发；一切修改都表现为「写新文件加 manifest 原子切换」，而不是在旧数据上动手。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重算写放大、读放大与空间放大的账（主干 compaction 课已有），不写布隆参数（读放大课已有），也不展开写停顿的流控——只立一条：flush 与 compaction 是预算内的后台债务，追不上写速时先停写入，别让内存表无限长。WiscKey 键值分离、tiered 与 leveled 的折中（<a href="/cs/leveled-tiered-compaction">leveled 对 tiered</a>），都是在这副骨架上换参数或换文件格式，不动组件边界。</p><p><span class="marginnote">写停顿可以想成洗碗：池子（内存表）有限，洗碗速度（compaction）跟不上上菜速度（写入）时，唯一正确的动作是先别上菜——短暂挡住写入，而不是让池子溢到地上。LSM 用这种可控的短期停顿，换长期不崩溃。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五件套：WAL、跳表内存表、冻结队列、带校验的不可变 SST、作为唯一真相的 manifest。</li><li>两条不变量：文件不可变（读免闩）；同键版本按序号全序（快照即比较）。</li><li>墓碑只能在最底层 compaction 丢弃，早丢即删除键复活。</li><li>读是归并迭代器；compaction 是后台归并加 manifest 原子切换。</li><li>出处：O&#39;Neil et al., <em>Acta Informatica</em>, 1996；LevelDB 与 RocksDB 设计文档。</li></ul>',6))])}const S=A(c,[["render",p]]);export{D as __pageData,S as default};
